body:
@CharliePoole  Thanks! So for now `CollectionAssert.AreEqual` will ignore any implement of `IEquatable`, and `Assert.AreEqual` will use any implement of `IEquatable`, right?

I list 4 tests below.  what is the specific use case for `CollectionAssert.AreEqual`? For Test3 and Test4, if we want to compare only the elements of the collection, we could both use `Assert.AreEqual( set1.ToArray(), set2.ToArray() );` instead.  Is there any case we could not use `Assert.AreEqual` instead of `CollectionAssert.AreEqual`?

And a more general question is that  When comparing set1 and set2, what is supposed to be compared? what's the common sense here?

```
namespace Nunit3TestsSamples {
	[TestFixture]
	class TestSample1 {

		[Test]
		public void Test1_WithoutIEquatable() {
			var set1 = new string[] { "x", "y", "z" };
			var set2 = new string[] { "x", "y", "z" };

			Assert.AreEqual( set1, set2 );
			CollectionAssert.AreEqual( set1, set2 );
		}

		[Test]
		public void Test2_WithElementIEquatable() {
			var set1 = new List<TestObject>() {
				new TestObject { Value = "test1" },
				new TestObject { Value = "test2" },
				new TestObject { Value = "test3" }
			};
			var set2 = new List<TestObject>() {
				new TestObject { Value = "test1" },
				new TestObject { Value = "test2" },
				new TestObject { Value = "test3" }
			};

			Assert.AreEqual( set1, set2 );
			//CollectionAssert.AreEqual( set1, set2);	//fail, since CollectionAssert.AreEqual will ignore IEquatable of Element TestObject
		}

		[Test]
		public void Test3_WithCollectionIEquatable() {
			var set1 = ImmutableArray.Create( "x", "y", "z" );
			var set2 = ImmutableArray.Create( "x", "y", "z" );

			Assert.IsFalse( set1.Equals(set2) );
			//Assert.AreEqual( set1, set2 );	//fail, since Assert.AreEqual will use the IEquatable of Collection ImmutableArray
			CollectionAssert.AreEqual( set1, set2);
		}

		[Test]
		public void Test4_WithCollectionAndElementIEquatable() {
			var set1 = ImmutableArray.Create(
				new TestObject { Value = "test1" },
				new TestObject { Value = "test2" },
				new TestObject { Value = "test3" } );
			var set2 = ImmutableArray.Create(
				new TestObject { Value = "test1" },
				new TestObject { Value = "test2" },
				new TestObject { Value = "test3" } );

			Assert.IsFalse( set1.Equals( set2 ) );
			//Assert.AreEqual( set1, set2 );	//fail, since Assert.AreEqual will use the IEquatable of Collection ImmutableArray
			//CollectionAssert.AreEqual( set1, set2 );	//fail, since CollectionAssert.AreEqual will ignore IEquatable of Element TestObject
		}

		class TestObject : IEquatable<TestObject> {
			public string Value { get; set; }

			public bool Equals( TestObject other ) {
				return Value.Equals( other.Value );
			}
		}
	}
}
```
